begin;create extension if not exists pgtap with schema extensions;select plan(44);
create schema if not exists test;create function test.login(id uuid) returns void language plpgsql as $$begin perform set_config('request.jwt.claim.sub',id::text,true);perform set_config('request.jwt.claim.role','authenticated',true);end$$;grant usage on schema test to anon,authenticated;grant execute on function test.login(uuid) to anon,authenticated;
set local role anon;select is((select count(*) from public.customers),0::bigint,'anonymous reads no customers');reset role;
set local role authenticated;select test.login('00000000-0000-4000-8000-000000000001');select is((select count(*) from customers),1::bigint,'customer A sees self');select is((select count(*) from customers where id='20000000-0000-4000-8000-000000000002'),0::bigint,'customer A cannot read B');select is((select count(*) from routes),0::bigint,'customer sees no CRM routes');select is((select count(*) from service_visits where customer_id='20000000-0000-4000-8000-000000000002'),0::bigint,'customer sees no other visits');update customers set full_name='attack' where id='20000000-0000-4000-8000-000000000002';select is((select count(*) from customers where full_name='attack'),0::bigint,'customer cannot modify B');select throws_like($$update customers set account_status='attack' where id='20000000-0000-4000-8000-000000000001'$$,'%Customers may update only their phone number%','customer cannot alter protected self fields');select lives_ok($$update customers set phone='555-010-1999' where id='20000000-0000-4000-8000-000000000001'$$,'customer may update own phone');select throws_like($$update user_profiles set login_status='disabled' where id='00000000-0000-4000-8000-000000000001'$$,'%Customers may update only their display name and phone%','customer cannot alter protected profile fields');select throws_like($$update bins set description='attack' where service_address_id='30000000-0000-4000-8000-000000000001'$$,'%Customers may update only the dirty-this-visit flag%','customer cannot alter protected bin fields');select throws_like($$insert into customer_change_requests(customer_id,service_address_id,request_type,requested_value,requested_by,reviewed_by) values('20000000-0000-4000-8000-000000000001','30000000-0000-4000-8000-000000000001','return_location','{"value":"porch"}','00000000-0000-4000-8000-000000000001','00000000-0000-4000-8000-000000000010')$$,'%row-level security%','customer cannot fabricate review metadata');
select test.login('00000000-0000-4000-8000-000000000011');update service_plan_versions set base_price_cents=1;select is((select count(*) from service_plan_versions where base_price_cents=1),0::bigint,'dispatcher cannot price');update subscriptions set service_status='attack';select is((select count(*) from subscriptions where service_status='attack'),0::bigint,'dispatcher cannot subscriptions');update referral_credits set remaining_cents=0;select is((select count(*) from referral_credits where remaining_cents=0),0::bigint,'dispatcher cannot credits');delete from staff_roles;select is((select count(*) from staff_roles where user_id=auth.uid()),1::bigint,'dispatcher cannot delete own role');select throws_like($$insert into audit_events(actor_id,action,entity_table,entity_key) values(auth.uid(),'FABRICATED','customers','fake')$$,'%row-level security%','staff cannot fabricate raw audit events');
select test.login('00000000-0000-4000-8000-000000000012');select is((select count(*) from routes),1::bigint,'assigned tech sees route');select is((select count(*) from cleaning_day_assignments),1::bigint,'assigned tech sees only assigned cleaning day');select is((select count(*) from service_visits),1::bigint,'assigned tech sees one visit');select is((select count(*) from customers),1::bigint,'tech sees only assigned customer');select is((select count(*) from customers where id='20000000-0000-4000-8000-000000000002'),0::bigint,'tech cannot browse unrelated customer');select is((select count(*) from subscriptions),0::bigint,'tech sees no finances');select lives_ok($$update service_visits set status='bins_returned' where id='80000000-0000-4000-8000-000000000001'$$,'tech may advance assigned visit');select is((select count(*) from visit_status_history where service_visit_id='80000000-0000-4000-8000-000000000001' and from_status='after_photo_complete' and to_status='bins_returned' and actor_id=auth.uid()),1::bigint,'status transitions generate trusted visit history');select throws_like($$insert into visit_status_history(service_visit_id,from_status,to_status,actor_id) values('80000000-0000-4000-8000-000000000001','scheduled','completed',auth.uid())$$,'%row-level security%','technician cannot fabricate visit history');select throws_like($$update service_visits set assigned_technician_id='00000000-0000-4000-8000-000000000013' where id='80000000-0000-4000-8000-000000000001'$$,'%Technicians may update only visit progress fields%','tech cannot reassign');select throws_like($$update service_visits set customer_id='20000000-0000-4000-8000-000000000002' where id='80000000-0000-4000-8000-000000000001'$$,'%Technicians may update only visit progress fields%','tech cannot alter visit relationships');select throws_like($$insert into service_exceptions(service_visit_id,exception_type,details,authorized_return_exception,status,recorded_by) values('80000000-0000-4000-8000-000000000001','return_exception','TECH CANNOT AUTHORIZE',true,'authorized','00000000-0000-4000-8000-000000000012')$$,'%row-level security%','tech cannot self-authorize return exception');select lives_ok($$insert into service_exceptions(service_visit_id,exception_type,details,authorized_return_exception,status,recorded_by) values('80000000-0000-4000-8000-000000000001','return_exception','TECH OPEN EXCEPTION',false,'open','00000000-0000-4000-8000-000000000012')$$,'tech may record open exception');
select test.login('00000000-0000-4000-8000-000000000013');select is((select count(*) from routes),0::bigint,'unassigned tech sees no routes');select is((select count(*) from cleaning_day_assignments),0::bigint,'unassigned tech sees no cleaning days');select is((select count(*) from service_visits),0::bigint,'unassigned tech sees no visits');select is((select count(*) from service_addresses),0::bigint,'unassigned tech sees no customer address');
select test.login('00000000-0000-4000-8000-000000000010');select is((select count(*) from customers),4::bigint,'administrator sees all customers');select lives_ok($$update service_exceptions set authorized_return_exception=true,status='authorized' where details='TECH OPEN EXCEPTION'$$,'administrator may authorize recorded exception');select lives_ok($$update customers set phone=phone where id='20000000-0000-4000-8000-000000000002'$$,'admin may update customer');select ok((select count(*)>0 from audit_events where entity_id='20000000-0000-4000-8000-000000000002' and action='UPDATE'),'protected mutation audited');select throws_ok($$update service_visits set status='completed',cleaning_confirmed=true,bins_returned=true where id='80000000-0000-4000-8000-000000000002';set constraints enforce_visit_completion immediate$$,'Completion requires before/after photos, cleaning, and bin return or authorized exception','photos enforced');select lives_ok($$update service_visits set status='completed',completed_at=now() where id='80000000-0000-4000-8000-000000000001';set constraints enforce_visit_completion immediate$$,'documented visit completes');update staff_roles set revoked_at=now() where user_id='00000000-0000-4000-8000-000000000012';select test.login('00000000-0000-4000-8000-000000000012');select is((select count(*) from routes),0::bigint,'revoked technician sees no routes');select is((select count(*) from service_visits),0::bigint,'revoked technician sees no visits');select is((select count(*) from customers),0::bigint,'revoked technician sees no assigned customers');select is((select count(*) from service_addresses),0::bigint,'revoked technician sees no addresses');select is((select count(*) from bins),0::bigint,'revoked technician sees no bins');select is((select count(*) from visit_photographs),0::bigint,'revoked technician sees no photos');
select * from finish();rollback;
